mapper.select:
SELECT d.id, d.dept_code, d.dept_name, d.org_id, d.parent_id, d.status, d.sort_no, d.created_at, d.updated_at, d.is_deleted AS isDeleted, d.deleted_at AS deletedAt, d.deleted_by AS deletedBy FROM sys_department d
AND (d.dept_name LIKE CONCAT('%', #{keyword}, '%') OR d.dept_code LIKE CONCAT('%', #{keyword}, '%'))
AND d.org_id = #{orgId}
AND d.org_id IN
#{scopeOrgId}
AND 1 = 0
ORDER BY d.org_id ASC, d.sort_no ASC, d.id ASC LIMIT #{limit}

mapper.update:
UPDATE sys_department
dept_name = #{deptName}, parent_id = #{parentId}, sort_no = #{sortNo},
WHERE id = #{id}

